from demos import scale_demo, squarecube_demo, pendulum_demo, polygon_demo, radial_demo, thirds_demo, spec_demo, list_demo

def T(t, g, sub, how, points, cite, demo=None, data=None, sig_points=None, req=None, std=None):
    d = {'t': t, 'g': g, 'sub': sub, 'how': how, 'points': points,
         'req': req or ['Basic tools for the craft', 'A clean, well-lit workspace',
                        'Reference images of the subject', 'Patience for fine detail work'],
         'std': std or ['Finished piece matches the described design',
                        'Details are clean and deliberate at the intended viewing distance',
                        'Materials are used safely and as intended'],
         'cite': cite, 'demo_kind': demo[0], 'demo_program': demo[1], 'demo_note': demo[2]}
    if data: d['data'] = data
    if sig_points: d['sig_points'] = sig_points
    return d

